/**
 * @vitest-environment jsdom
 */
import { hrTimeToMilliseconds } from '@opentelemetry/core'
import { InMemorySpanExporter, SimpleSpanProcessor } from '@opentelemetry/sdk-trace-web'
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from 'vite-plus/test'

import { configure, startSpan } from './index'

vi.mock('@opentelemetry/exporter-trace-otlp-http', () => ({
  OTLPTraceExporter: class {
    export(_spans: unknown, resultCallback: (result: { code: number }) => void): void {
      resultCallback({ code: 0 })
    }

    async shutdown(): Promise<void> {
      return Promise.resolve()
    }
  },
}))

const exporter = new InMemorySpanExporter()
let preventSpanCreation = false
let cleanup: (() => Promise<void>) | undefined
const startupListener = (): void => undefined

beforeAll(() => {
  cleanup = configure({
    autoInstrumentations: {
      '@opentelemetry/instrumentation-document-load': { enabled: false },
      '@opentelemetry/instrumentation-fetch': { enabled: false },
      '@opentelemetry/instrumentation-user-interaction': {
        eventNames: ['click'],
        shouldPreventSpanCreation: () => preventSpanCreation,
      },
      '@opentelemetry/instrumentation-xml-http-request': { enabled: false },
    },
    spanProcessors: [new SimpleSpanProcessor(exporter)],
    traceUrl: '/client-traces',
  })
  // Registered in the same task as configure(), as a framework root registers its delegated listeners
  // during application startup. The instrumentation never wraps a listener added before its patch.
  document.addEventListener('click', startupListener)
})

afterAll(async () => {
  document.removeEventListener('click', startupListener)
  await cleanup?.()
})

beforeEach(() => {
  preventSpanCreation = false
  exporter.reset()
  document.body.replaceChildren()
})

describe('browser user interaction spans', () => {
  it('exports a click span for a listener registered right after configure', async () => {
    const button = document.createElement('button')
    document.body.append(button)

    button.click()
    await nextTask()

    expect(clickSpans()).toHaveLength(1)
  })

  it('exports one click span when one click reaches several listeners', async () => {
    const { button, removeListeners } = mountButtonWithListeners()

    button.click()
    removeListeners()
    await nextTask()

    const clicks = clickSpans()
    expect(clicks).toHaveLength(1)
    expect(clicks[0]?.parentSpanContext).toBeUndefined()
  })

  it('parents work that a later listener starts to the click span', async () => {
    const { button, removeListeners } = mountButtonWithListeners(() => {
      startSpan('work started by a later listener').end()
    })

    button.click()
    removeListeners()
    await nextTask()

    const clicks = clickSpans()
    const work = exporter.getFinishedSpans().find(({ name }) => name === 'work started by a later listener')
    expect(clicks).toHaveLength(1)
    expect(work?.spanContext().traceId).toBe(clicks[0]?.spanContext().traceId)
    expect(work?.parentSpanContext?.spanId).toBe(clicks[0]?.spanContext().spanId)
  })

  it('starts a separate trace for each consecutive click', async () => {
    const { button, removeListeners } = mountButtonWithListeners()

    button.click()
    button.click()
    removeListeners()
    await nextTask()
    await nextTask()

    const clicks = clickSpans()
    expect(clicks).toHaveLength(2)
    expect(clicks.map((span) => span.parentSpanContext)).toEqual([undefined, undefined])
    expect(clicks[0]?.spanContext().traceId).not.toBe(clicks[1]?.spanContext().traceId)
  })

  it('keeps a configured shouldPreventSpanCreation hook in effect', async () => {
    preventSpanCreation = true
    const calls: string[] = []
    const { button, removeListeners } = mountButtonWithListeners(() => {
      calls.push('app')
    })

    button.click()
    removeListeners()
    await nextTask()

    expect(clickSpans()).toEqual([])
    expect(calls).toEqual(['app'])
  })

  it('keeps the click span open until the last listener returns', async () => {
    const lastListenerMs = 30
    const { button, removeListeners } = mountButtonWithListeners(() => {
      const start = performance.now()
      while (performance.now() - start < lastListenerMs) {
        // Busy work in the last listener, which a span that ends with the first listener excludes.
      }
    })

    button.click()
    removeListeners()
    await nextTask()

    const clicks = clickSpans()
    expect(clicks).toHaveLength(1)
    // The span clock converts between wall and performance time, so allow a few milliseconds.
    expect(hrTimeToMilliseconds(clicks[0]?.duration ?? [0, 0])).toBeGreaterThanOrEqual(lastListenerMs - 5)
  })

  it('ends the click span when a listener throws', async () => {
    const button = document.createElement('button')
    document.body.append(button)
    button.addEventListener('click', () => {
      throw new Error('listener failed')
    })
    const ignoreReportedError = (event: Event) => {
      event.preventDefault()
    }
    window.addEventListener('error', ignoreReportedError)

    button.click()
    await nextTask()
    window.removeEventListener('error', ignoreReportedError)

    expect(clickSpans()).toHaveLength(1)
  })
})

function mountButtonWithListeners(appListener: () => void = () => undefined): {
  button: HTMLButtonElement
  removeListeners: () => void
} {
  const button = document.createElement('button')
  button.textContent = 'Save'
  document.body.append(button)
  // A capture listener on the document runs before the application handler, as a session
  // recorder's listener does. The application handler is the last listener the click reaches.
  const captureListener = (): void => undefined
  const buttonListener = (): void => undefined
  document.addEventListener('click', captureListener, true)
  button.addEventListener('click', buttonListener)
  document.addEventListener('click', appListener)
  return {
    button,
    removeListeners: () => {
      document.removeEventListener('click', captureListener, true)
      button.removeEventListener('click', buttonListener)
      document.removeEventListener('click', appListener)
    },
  }
}

async function nextTask(): Promise<void> {
  await new Promise((resolve) => {
    setTimeout(resolve, 0)
  })
}

function clickSpans(): ReturnType<InMemorySpanExporter['getFinishedSpans']> {
  return exporter.getFinishedSpans().filter(({ name }) => name === 'click' || name.startsWith('click '))
}

/* eslint-disable no-underscore-dangle -- The tests drive private members of the upstream user interaction instrumentation. */
import type { Span } from '@opentelemetry/api'
import { diag, trace } from '@opentelemetry/api'
import type { Instrumentation } from '@opentelemetry/instrumentation'
import { afterEach, describe, expect, it, vi } from 'vite-plus/test'

import { collapseUserInteractionSpans } from './userInteraction'

const parentSpan = trace.wrapSpanContext({ spanId: '0123456789abcdef', traceFlags: 1, traceId: '0123456789abcdef0123456789abcdef' })
const createdSpan = trace.wrapSpanContext({ spanId: 'fedcba9876543210', traceFlags: 1, traceId: 'fedcba9876543210fedcba9876543210' })

type CreateSpan = (element: unknown, eventName: string, parentSpan?: Span) => Span | undefined

interface FakeUserInteraction {
  _createSpan?: CreateSpan | undefined
  _isEnabled?: boolean
  instrumentationName: string
}

function fakeInstrumentation(overrides: Partial<FakeUserInteraction> = {}): FakeUserInteraction {
  return {
    _createSpan: vi.fn<CreateSpan>(() => createdSpan),
    _isEnabled: true,
    instrumentationName: '@opentelemetry/instrumentation-user-interaction',
    ...overrides,
  }
}

afterEach(() => {
  vi.useRealTimers()
  vi.restoreAllMocks()
})

describe('collapseUserInteractionSpans', () => {
  it('reuses the span context of the first listener for later listeners of the same event', () => {
    const instrumentation = fakeInstrumentation()
    const createSpan = instrumentation._createSpan

    collapseUserInteractionSpans([instrumentation as unknown as Instrumentation])

    const span = instrumentation._createSpan?.('element', 'click', parentSpan)
    expect(span?.spanContext()).toEqual(parentSpan.spanContext())
    expect(span?.isRecording()).toBe(false)
    expect(createSpan).not.toHaveBeenCalled()
  })

  it('creates the first span through the instrumentation', () => {
    const instrumentation = fakeInstrumentation()
    const createSpan = instrumentation._createSpan

    collapseUserInteractionSpans([instrumentation as unknown as Instrumentation])

    expect(instrumentation._createSpan?.('element', 'click')).toBe(createdSpan)
    expect(createSpan).toHaveBeenCalledWith('element', 'click', undefined)
  })

  it('ends the first span one task later, at the time the last listener returned', () => {
    vi.useFakeTimers()
    const end = vi.fn<(endTime?: number) => void>()
    const firstSpan = { end, spanContext: () => createdSpan.spanContext() } as unknown as Span
    const instrumentation = fakeInstrumentation({ _createSpan: vi.fn<CreateSpan>(() => firstSpan) })
    vi.spyOn(performance, 'now').mockReturnValueOnce(10).mockReturnValueOnce(25).mockReturnValueOnce(40)
    collapseUserInteractionSpans([instrumentation as unknown as Instrumentation])

    const span = instrumentation._createSpan?.('element', 'click')
    span?.end()
    // The instrumentation passes each listener the span it returned for the previous listener.
    const secondListenerSpan = instrumentation._createSpan?.('element', 'click', span)
    secondListenerSpan?.end()
    instrumentation._createSpan?.('element', 'click', secondListenerSpan)?.end()
    expect(end).not.toHaveBeenCalled()
    vi.runAllTimers()

    expect(end.mock.calls).toEqual([[40]])
  })

  it('delegates to the instrumentation after it is disabled', () => {
    const instrumentation = fakeInstrumentation({ _createSpan: vi.fn<CreateSpan>(() => undefined), _isEnabled: false })
    const createSpan = instrumentation._createSpan

    collapseUserInteractionSpans([instrumentation as unknown as Instrumentation])

    expect(instrumentation._createSpan?.('element', 'click', parentSpan)).toBeUndefined()
    expect(createSpan).toHaveBeenCalledWith('element', 'click', parentSpan)
  })

  it('leaves other instrumentations unchanged', () => {
    const createSpan = vi.fn<CreateSpan>(() => createdSpan)
    const instrumentation = fakeInstrumentation({ _createSpan: createSpan, instrumentationName: '@opentelemetry/instrumentation-fetch' })

    collapseUserInteractionSpans([instrumentation as unknown as Instrumentation])

    expect(instrumentation._createSpan).toBe(createSpan)
  })

  it('warns and keeps the instrumentation unchanged when _createSpan is missing', () => {
    const warn = vi.spyOn(diag, 'warn').mockImplementation(() => undefined)
    const instrumentation = fakeInstrumentation({ _createSpan: undefined })

    collapseUserInteractionSpans([instrumentation as unknown as Instrumentation])

    expect(instrumentation._createSpan).toBeUndefined()
    expect(warn).toHaveBeenCalledWith(
      'logfire-browser: the user interaction instrumentation has no _createSpan; it can export one span per event listener'
    )
  })
})

import { gunzipSync } from 'node:zlib'

import { expect, test as base } from '@playwright/test'

import type { ChunkEnvelope } from '../src/types'
import type { ReplayReceipt } from '../test-fixtures/delivery/vite.config'

const test = base.extend({
  channel: async ({ browserName }, use) => {
    await use(browserName === 'chromium' ? 'chromium' : undefined)
  },
})

// Playwright disables Chromium's BFCache by default. This flow must restore
// the original document, not merely reload the same URL from history.
test.use({ launchOptions: { ignoreDefaultArgs: ['--disable-back-forward-cache'] } })

test('Chromium BFCache restores a fresh recorder at the latest sequence', async ({ page, request, context, browserName }, testInfo) => {
  test.skip(browserName !== 'chromium', 'Native cache restoration is verified with full Chromium; WebKit identity flows run separately.')
  await request.post('http://127.0.0.1:4177/fixture/reset?scenario=identity')
  await page.goto('http://127.0.0.1:4177/identity.html')
  await expect(page.getByRole('status')).toHaveText('ready')
  const original = await page.evaluate(() => ({
    documentId: window.logfireReplayIdentity.documentId,
    recordingId: window.logfireReplayIdentity.recordingId,
  }))
  await page.getByRole('link', { name: 'Navigate in this tab' }).click()
  await expect(page.getByRole('status')).toHaveText('ready')
  expect(await page.evaluate(() => window.logfireReplayIdentity.documentId)).not.toBe(original.documentId)
  const before = await page.evaluate(() => sessionStorage.getItem('lf_session_replay_seq'))
  expect(await page.evaluate(() => window.logfireReplayIdentity.recordingId)).toBe(original.recordingId)
  await page.goBack({ waitUntil: 'commit' })
  await testInfo.attach('back-navigation', {
    body: await page.evaluate(() =>
      JSON.stringify({
        navigation: performance.getEntriesByType('navigation').map((entry) => ({ name: entry.name, type: entry.entryType })),
        restoreStates: window.logfireReplayIdentity.restoreStates,
      })
    ),
    contentType: 'application/json',
  })
  await expect.poll(async () => page.evaluate(() => window.logfireReplayIdentity.pageShows)).toEqual([false, true])
  try {
    expect(await page.evaluate(() => window.logfireReplayIdentity.documentId)).toBe(original.documentId)
    await page.evaluate(async () => window.logfireReplayIdentity.flush())
    expect(await page.evaluate(() => window.logfireReplayIdentity.recordingId)).toBe(original.recordingId)
    const after = await page.evaluate(() => sessionStorage.getItem('lf_session_replay_seq'))
    const beforeSequence = JSON.parse(before ?? '{}') as { id: string; seq: number }
    const afterSequence = JSON.parse(after ?? '{}') as { id: string; seq: number }
    expect(afterSequence.id).toBe(original.recordingId)
    expect(afterSequence.seq).toBeGreaterThan(beforeSequence.seq)
    await page.evaluate(async () => window.logfireReplayIdentity.stop())
    const response = await request.get('http://127.0.0.1:4177/fixture/status?scenario=identity')
    expect(response.ok()).toBe(true)
    const evidence = (await response.json()) as { receipts: ReplayReceipt[] }
    const receipts = evidence.receipts.filter(
      (receipt) => new URL(receipt.url, 'http://127.0.0.1:4177').pathname === `/replay/identity/${original.recordingId}`
    )
    expect(receipts.every((receipt) => receipt.accepted)).toBe(true)
    expect(new Set(receipts.map((receipt) => receipt.seq)).size).toBe(receipts.length)
    const restored = receipts.find((receipt) => receipt.seq === afterSequence.seq - 1)
    expect(restored).toBeDefined()
    if (restored === undefined) {
      throw new Error('No restored recording was uploaded')
    }
    const envelope = JSON.parse(gunzipSync(Buffer.from(restored.body, 'base64')).toString('utf8')) as ChunkEnvelope
    expect(envelope.events.map((event) => event.type)).toEqual(expect.arrayContaining([4, 2]))
    const playback = await context.newPage()
    try {
      await playback.goto('http://127.0.0.1:4177/playback.html')
      await playback.evaluate(async (events) => window.logfireReplayPlayback.load(events), envelope.events)
      await expect(playback.frameLocator('iframe').getByText('parent-marker', { exact: true })).toBeVisible()
    } finally {
      await playback.close()
    }
  } finally {
    await page.evaluate(async () => window.logfireReplayIdentity.stop())
  }
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import {
  configureVariables,
  defineTemplateVar,
  defineVar,
  getVariableProvider,
  variablesPullConfig,
  variablesClear,
  variablesPush,
  variablesValidate,
} from './index'
import type { VariablesConfig } from './index'
import { extractTemplatePaths, validateTemplateInputs } from './templateValidation'

const config = (variables: VariablesConfig['variables']): VariablesConfig => ({ variables })

describe('variable template validation', () => {
  beforeEach(() => {
    variablesClear()
    configureVariables(false)
  })

  afterEach(async () => {
    await getVariableProvider().shutdown?.()
    vi.restoreAllMocks()
    variablesClear()
    configureVariables(false)
  })

  it('does not report item fields inside an each block as missing template inputs', () => {
    const schema = {
      properties: { items: { items: { properties: { name: { type: 'string' } }, type: 'object' }, type: 'array' } },
      type: 'object',
    }

    expect(validateTemplateInputs(JSON.stringify('{{#each items}}{{name}}{{/each}}'), schema, 'v', undefined)).toEqual([])
    // The inverse block runs against the enclosing context, so an unknown path there is still reported.
    expect(
      validateTemplateInputs(JSON.stringify('{{#each items}}{{name}}{{else}}{{missing}}{{/each}}'), schema, 'v', undefined).map(
        (issue) => issue.path
      )
    ).toEqual(['missing'])
  })

  it('extracts common Handlebars paths from templates', () => {
    expect(extractTemplatePaths('Hello {{user.name}} {{#if beta}}yes{{/if}}')).toEqual(['user.name', 'beta'])
    // `each` and `with` shift the context, so a bare path in the program body belongs to the item,
    // not to the template inputs. The inverse block still runs against the enclosing context.
    expect(extractTemplatePaths('{{#each items}}{{name}}{{/each}}')).toEqual(['items'])
    expect(extractTemplatePaths('{{#with brand}}{{tagline}}{{/with}}')).toEqual(['brand'])
    expect(extractTemplatePaths('{{#each items}}{{name}}{{else}}{{fallback}}{{/each}}')).toEqual(['items', 'fallback'])
    // A parent-scoped path is still dropped by shouldValidatePath, unchanged by the depth model.
    expect(extractTemplatePaths('{{#each items}}{{../heading}}{{/each}}')).toEqual(['items'])
  })

  it('allows template paths covered by object-valued additionalProperties', () => {
    expect(
      validateTemplateInputs(
        JSON.stringify('Hello {{name}} {{extra}}'),
        {
          additionalProperties: { type: 'string' },
          properties: { name: { type: 'string' } },
          type: 'object',
        },
        'prompt',
        'prod'
      )
    ).toEqual([])
  })

  it('reports template paths rejected by additionalProperties false without explicit properties', () => {
    expect(
      validateTemplateInputs(
        JSON.stringify('Hello {{extra}}'),
        {
          additionalProperties: false,
          type: 'object',
        },
        'prompt',
        'prod'
      )
    ).toEqual([
      {
        label: 'prod',
        message: "Template path 'extra' is not present in template_inputs_schema",
        path: 'extra',
        variableName: 'prompt',
      },
    ])
  })

  it('reports template paths missing from template_inputs_schema', async () => {
    configureVariables({
      config: config({
        prompt: {
          labels: { prod: { serialized_value: JSON.stringify('Hello {{missing}}'), version: 1 } },
          name: 'prompt',
          overrides: [],
          rollout: { labels: { prod: 1 } },
        },
      }),
      instrument: false,
    })
    const prompt = defineTemplateVar<string, { name: string }>('prompt', {
      default: 'Hello {{name}}',
      templateInputsSchema: {
        properties: { name: { type: 'string' } },
        type: 'object',
      },
    })

    const report = await variablesValidate([prompt])

    expect(report.isValid).toBe(false)
    expect(report.templateFieldIssues).toEqual([
      {
        fieldName: 'missing',
        foundInLabel: 'prod',
        foundInVariable: 'prompt',
        message: "Template path 'missing' is not present in template_inputs_schema",
        referencePath: ['prompt'],
        rootVariable: 'prompt',
      },
    ])
  })

  it('validates templates after transitive composition', async () => {
    configureVariables({
      config: config({
        fragment: {
          labels: { prod: { serialized_value: JSON.stringify('{{unknown}}'), version: 1 } },
          name: 'fragment',
          overrides: [],
          rollout: { labels: { prod: 1 } },
        },
        prompt: {
          labels: { prod: { serialized_value: JSON.stringify('Use @{fragment}@'), version: 1 } },
          name: 'prompt',
          overrides: [],
          rollout: { labels: { prod: 1 } },
        },
      }),
      instrument: false,
    })
    const prompt = defineTemplateVar<string, { known: string }>('prompt', {
      default: 'Use {{known}}',
      templateInputsSchema: {
        properties: { known: { type: 'string' } },
        type: 'object',
      },
    })

    const report = await variablesValidate([prompt])

    expect(report.templateFieldIssues).toMatchObject([
      {
        fieldName: 'unknown',
        foundInLabel: 'prod',
        foundInVariable: 'fragment',
        referencePath: ['prompt', 'fragment'],
        rootVariable: 'prompt',
      },
    ])
  })

  it('reports missing references and cycles', async () => {
    configureVariables({
      config: config({
        cyclic: {
          labels: { prod: { serialized_value: JSON.stringify('@{cyclic}@'), version: 1 } },
          name: 'cyclic',
          overrides: [],
          rollout: { labels: { prod: 1 } },
        },
        prompt: {
          labels: { prod: { serialized_value: JSON.stringify('@{missing}@'), version: 1 } },
          name: 'prompt',
          overrides: [],
          rollout: { labels: { prod: 1 } },
        },
      }),
      instrument: false,
    })
    const prompt = defineVar('prompt', { default: '' })
    const cyclic = defineVar('cyclic', { default: '' })

    const report = await variablesValidate([prompt, cyclic])

    expect(report.referenceErrors).toEqual([
      "Variable 'prompt' references missing variable 'missing' via prompt -> missing",
      'Circular variable reference: cyclic -> cyclic',
    ])
    expect(report.referenceCycles).toEqual(['Circular variable reference: cyclic -> cyclic'])
    expect(report.isValid).toBe(false)
  })

  it('reports invalid reference syntax without throwing during validation', async () => {
    configureVariables({
      config: config({
        prompt: {
          labels: { prod: { serialized_value: JSON.stringify('Hello @{#if missing}@'), version: 1 } },
          name: 'prompt',
          overrides: [],
          rollout: { labels: { prod: 1 } },
        },
      }),
      instrument: false,
    })
    const prompt = defineVar('prompt', { default: '' })

    const report = await variablesValidate([prompt])

    expect(report.isValid).toBe(false)
    expect(report.referenceErrors).toHaveLength(1)
    expect(report.referenceErrors[0]).toContain("Variable 'prompt' has invalid reference syntax in 'prompt:prod'")
  })

  it('strict push returns a blocked result for reference and template validation issues', async () => {
    configureVariables({
      config: config({
        prompt: {
          labels: { prod: { serialized_value: JSON.stringify('Hello {{missing}} @{unknown}@'), version: 1 } },
          name: 'prompt',
          overrides: [],
          rollout: { labels: { prod: 1 } },
        },
      }),
      instrument: false,
    })
    const prompt = defineTemplateVar<string, { name: string }>('prompt', {
      default: 'Hello {{name}}',
      templateInputsSchema: {
        properties: { name: { type: 'string' } },
        type: 'object',
      },
    })

    await expect(variablesPush([prompt], { strict: true })).resolves.toMatchObject({
      blocked: true,
      blockedBy: ['reference_errors'],
      changes: [{ action: 'update', name: 'prompt' }],
      dryRun: false,
    })
  })

  it('non-strict push warns and applies reference and template validation issues', async () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined)
    configureVariables({
      config: config({
        prompt: {
          labels: { prod: { serialized_value: JSON.stringify('Hello {{missing}} @{unknown}@'), version: 1 } },
          name: 'prompt',
          overrides: [],
          rollout: { labels: { prod: 1 } },
        },
      }),
      instrument: false,
    })
    const prompt = defineTemplateVar<string, { name: string }>('prompt', {
      default: 'Hello {{name}}',
      templateInputsSchema: {
        properties: { name: { type: 'string' } },
        type: 'object',
      },
    })

    await expect(variablesPush([prompt])).resolves.toMatchObject({
      blocked: false,
      blockedBy: [],
      changes: [{ action: 'update', name: 'prompt' }],
      dryRun: false,
    })
    expect(warn).toHaveBeenCalledWith(expect.stringContaining('Variable push reference warning'))
    expect(warn).toHaveBeenCalledWith(expect.stringContaining('Variable push template warning'))
    await expect(variablesPullConfig()).resolves.toMatchObject({
      variables: {
        prompt: {
          template_inputs_schema: {
            properties: { name: { type: 'string' } },
            type: 'object',
          },
        },
      },
    })
  })
})

